const res = $input.first().json;
let parsed = {};
try {
  let content = res.choices[0].message.content;
  if (typeof content === 'string') {
    content = content.replace(/^```json\s*/, '').replace(/```\s*$/, '').trim();
    parsed = JSON.parse(content);
  } else {
    parsed = content;
  }
} catch (e) {
  parsed = { intent: 'QUESTION', reasoning: 'Could not parse JSON or model call failed: ' + (res.error ? res.error.message : e.message), suggested_action: 'Review manually in inbox' };
}

let parentItem = {};
try {
  parentItem = $('Merge Inbound with CRM Match').first().json;
} catch (e) {
  parentItem = {};
}

return [{
  json: {
    ...parentItem,
    intent: parsed.intent || 'QUESTION',
    ai_intent: parsed.intent || 'QUESTION',
    ai_reasoning: parsed.reasoning || '',
    ai_suggested_action: parsed.suggested_action || '',
    ai_confidence: parsed.confidence || 0.8
  }
}];

