={{ (() => {
  const webmail = ['gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
  const clean = s => String(s || '').toLowerCase().replace(/['"\\]/g, '').trim();
  if ($json.event_type === 'BOUNCE') {
    const em = clean($json.failed_recipient);
    const dom = clean($json.failed_domain);
    if (!em && !dom) return 'RECORD_ID() = ""';
    if (dom && !webmail.includes(dom)) return `OR({Email} = '${em}', {Domain} = '${dom}')`;
    return `{Email} = '${em}'`;
  }
  const em = clean($json.from_email);
  const dom = clean($json.from_domain);
  const rawSubj = String($json.subject || '');
  const isReply = /^\s*(re|fwd?|aw)\s*:/i.test(rawSubj);
  const subj = rawSubj.toLowerCase().trim().replace(/^((re|fwd?|aw)\s*:\s*)+/i, '').trim().replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  const clauses = [];
  if (em) clauses.push(`{Email} = '${em}'`);
  if (dom && !webmail.includes(dom)) clauses.push(`{Domain} = '${dom}'`);
  if (isReply && subj.length >= 8) clauses.push(`LOWER({Subject}) = '${subj}'`);
  if (!clauses.length) return 'RECORD_ID() = ""';
  return clauses.length > 1 ? `OR(${clauses.join(', ')})` : clauses[0];
})() }}

