// Matches the inbound email to a CRM company. Priority: exact sender email, then sender domain (non-webmail),
// then the reply subject ("Re: <original subject>") when it matches exactly ONE company. The subject fallback fixes
// opt-outs/replies sent from a different address (e.g. a personal Gmail) that previously stayed unmatched, left the
// domain unsuppressed and let follow-ups continue.
const webmail = ['gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
const inbound = $('Detect Bounce vs OOO vs Human Reply').first().json;
const results = $input.all().map(i => i.json).filter(r => r && r.id);

const normSubject = s => String(s || '').toLowerCase().trim().replace(/^((re|fwd?|aw)\s*:\s*)+/i, '').trim();
const isBounce = inbound.event_type === 'BOUNCE';
const em = String((isBounce ? inbound.failed_recipient : inbound.from_email) || '').toLowerCase().trim();
const dom = String((isBounce ? inbound.failed_domain : inbound.from_domain) || '').toLowerCase().trim();
const replySubject = /^\s*(re|fwd?|aw)\s*:/i.test(String(inbound.subject || '')) ? normSubject(inbound.subject) : '';

const f = r => r.fields || r;
let match = null, matchedBy = null;
match = results.find(r => em && String(f(r).Email || '').toLowerCase().trim() === em);
if (match) matchedBy = 'email';
if (!match && dom && !webmail.includes(dom)) {
  match = results.find(r => String(f(r).Domain || '').toLowerCase().trim() === dom);
  if (match) matchedBy = 'domain';
}
if (!match && !isBounce && replySubject.length >= 8) {
  const bySubject = results.filter(r => normSubject(f(r).Subject) === replySubject);
  if (bySubject.length === 1) { match = bySubject[0]; matchedBy = 'subject'; }
}

const matchedId = match ? match.id : null;
const matchedCompany = match ? (f(match).Name || f(match).Domain || null) : null;
const matchedDomain = match ? (String(f(match).Domain || '').toLowerCase().trim() || null) : null;

return [{
  json: {
    ...inbound,
    crm_matched_id: matchedId,
    crm_matched_company: matchedCompany,
    crm_matched_domain: matchedDomain,
    crm_is_matched: Boolean(matchedId),
    crm_matched_by: matchedBy
  }
}];
